/**
 * Retrato y escudos, tomados de felipeorma.com con permiso de su autor.
 *
 * Van incrustados como data URI y no enlazados al sitio por dos motivos: una
 * portada que depende de que otro dominio responda se queda coja el día que
 * ese dominio cambie de sitio, y el sitio se publica en GitHub Pages bajo un
 * subdirectorio donde una ruta absoluta se rompería. Los tres juntos pesan
 * trece kilobytes: menos que una sola petición de red.
 *
 * Los escudos están a la altura a la que se usan —56 px— porque un PNG de
 * 632 px de alto reducido por CSS pesa cuarenta veces más y se ve igual.
 */
export const RETRATO = "data:image/jpeg;base64,";

export const ESCUDOS: Record<"cavalry" | "maldonado", { src: string; ancho: number; alto: number; nombre: string }> = {
  cavalry: { nombre: "Cavalry FC", ancho: 44, alto: 56, src: "data:image/png;base64," },
  maldonado: { nombre: "Deportivo Maldonado", ancho: 42, alto: 56, src: "data:image/png;base64," },
};

/**
 * Los escudos para los informes, en alta resolución: van junto a la firma en
 * cada hoja y salen impresos, donde el de 56 px se veía borroso. De Wikipedia
 * (15 de octubre de 2026): el de Cavalry es vectorial (File:Cavalry FC
 * logo.svg) y el de Maldonado, el PNG de Commons (Escudo Deportivo
 * Maldonado.png) reducido a 256 px de alto.
 */
export const ESCUDOS_INFORME: Record<"cavalry" | "maldonado", string> = {
  cavalry: "data:image/svg+xml;base64,",
  maldonado: "data:image/png;base64,",
};
